import React, { useState, useEffect, useContext } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { AuthContext } from '../context/AuthContext';
import { toast } from 'react-toastify';

const Quiz = () => {
  const { category } = useParams();
  const { user } = useContext(AuthContext);
  const navigate = useNavigate();
  const [questions, setQuestions] = useState([]);
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState('');
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(30);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    fetchQuestions();
  }, [category, user, navigate]);

  useEffect(() => {
    if (timeLeft > 0) {
      const timer = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
      return () => clearTimeout(timer);
    } else {
      handleNext();
    }
  }, [timeLeft]);

  const fetchQuestions = async () => {
    try {
      const res = await axios.get(`http://localhost:5000/api/quiz/${category}`);
      setQuestions(res.data);
      setLoading(false);
    } catch (err) {
      toast.error('Failed to load questions');
    }
  };

  const handleAnswer = (answer) => {
    setSelectedAnswer(answer);
  };

  const handleNext = () => {
    if (selectedAnswer === questions[currentQuestion].correctAnswer) {
      setScore(score + 1);
    }
    setSelectedAnswer('');
    setTimeLeft(30);
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    } else {
      submitScore();
    }
  };

  const submitScore = async () => {
    try {
      await axios.post('http://localhost:5000/api/score', { category, score });
      toast.success(`Quiz completed! Your score: ${score}`);
      navigate('/');
    } catch (err) {
      toast.error('Failed to submit score');
    }
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="container mx-auto p-8 max-w-2xl">
      <h1 className="text-2xl font-bold mb-4">{category} Quiz</h1>
      <div className="mb-4">Time left: {timeLeft}s</div>
      <div className="mb-4">Question {currentQuestion + 1} of {questions.length}</div>
      <h2 className="text-xl mb-4">{questions[currentQuestion].question}</h2>
      {questions[currentQuestion].options.map((option, index) => (
        <button
          key={index}
          onClick={() => handleAnswer(option)}
          className={`block w-full p-2 mb-2 border ${selectedAnswer === option ? 'bg-blue-200' : ''}`}
        >
          {option}
        </button>
      ))}
      <button onClick={handleNext} className="mt-4 bg-blue-600 text-white p-2">Next</button>
    </div>
  );
};

export default Quiz;
